        // man's current partners
        for (int i = 0; i < n; i++) mPartner[i] = -1; 

        // next proposal index
        int[] next = new int[n]; 
        boolean[] freeMan = new boolean[n];

        // Free Men
        for (int i = 0; i < n; i++) freeMan[i] = true; 

        int freeCount = n;

        while (freeCount > 0) {
            int m;
            for (m = 0; m < n; m++)
                if (freeMan[m])
                    break;

            int w = men[m][next[m]];
