    using System;
using System.Collections.Generic;

public class GFG
{
    // Check if woman prefers m over current partner m1
    public static bool Prefers(List<List<int>> women, int w, int m, int m1)
    {
        for (int i = 0; i < women[w].Count; i++)
        {
            if (women[w][i] == m)
                return true;
            if (women[w][i] == m1)
                return false;
        }
        return false;
    }

    public static List<int> stableMarriage(List<List<int>> men, List<List<int>> women)
    {
        int n = men.Count;

        // women's current partners
        List<int> wPartner = new List<int>(new int[n]);

        // man's current partners
        List<int> mPartner = new List<int>(new int[n]);

        // next proposal index
        List<int> next = new List<int>(new int[n]);

        // Free Men
        List<bool> freeMan = new List<bool>(new bool[n]);

        for (int i = 0; i < n; i++)
        {
            wPartner[i] = -1;
            mPartner[i] = -1;
            next[i] = 0;
            freeMan[i] = true;
        }

        int freeCount = n;

        while (freeCount > 0)
        {
            int m = -1;
            for (int i = 0; i < n; i++)
            {
                if (freeMan[i])
                {
                    m = i;
                    break;
                }
            }

            int w = men[m][next[m]];
            next[m]++;

            // If w is free
            if (wPartner[w] == -1)
            {
                wPartner[w] = m;
                mPartner[m] = w;
                freeMan[m] = false;
                freeCount--;
            }
            else
            {
                int m1 = wPartner[w];

                // If w prefers m over current partner
                if (Prefers(women, w, m, m1))
                {
                    wPartner[w] = m;
                    mPartner[m] = w;

                    freeMan[m] = false;
                    freeMan[m1] = true;
                }
            }
        }

        return mPartner;
    }

    public static void Main()
    {
        int n = 3;

        List<List<int>> men = new List<List<int>>
        {
            new List<int> { 1, 0, 2 },
            new List<int> { 2, 1, 0 },
            new List<int> { 0, 2, 1 }
        };

        List<List<int>> women = new List<List<int>>
        {
            new List<int> { 1, 0, 2 },
            new List<int> { 2, 1, 0 },
            new List<int> { 0, 2, 1 }
        };

        List<int> result = stableMarriage(men, women);

        for (int i = 0; i < n; i++)
        {
            Console.Write(result[i]);
            if (i!= n - 1)
                Console.Write(" ");
        }
    }
}


